-- Área Operações: case básico "O fechamento" (op-simplificado) e case avançado "A cota que caiu 10%" (op-complexo).
-- Fonte: PDF de cases de Corporate Finance, Sales & Trading e Operações. Todos os dados são fictícios.

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  'op-simplificado',
  'Operações simplificado: o fechamento de quinta-feira',
  'operacoes',
  'Seja estagiária de operações num dia de fechamento: confira ordens, concilie posições, priorize pendências e reaja a um incidente.',
  'Conferir as ordens do dia, explicar uma diferença de conciliação, priorizar pendências e agir com procedimento diante de um incidente antes do horário-limite.',
  $$Quinta-feira, 16h40. Você é estagiária de operações da Arquipélago. Todas as ordens do dia precisam ser conferidas e enviadas para liquidação até as 18h. Marina, a gerente, está em reunião até as 17h30, e a Eva, sua mentora, está por perto para ajudar se você travar. Ao final, a banca (Helena, Ricardo e Paula) vai conversar com você sobre o que aconteceu. Todos os nomes, empresas e números são fictícios.$$,
  $${"resumo": "Operações é a área que faz o mercado financeiro acontecer de verdade: depois que a gestora decide comprar, o trader fecha o negócio ou o cliente pede um resgate, é Operações que registra, confere, liquida, guarda e controla. Neste case, você vive um fim de tarde de fechamento em que atenção a detalhe, conciliação, prioridade e comunicação fazem diferença.", "links": [], "cards": [{"titulo": "O que Operações faz", "texto": "Operações registra, confere, liquida (troca o ativo pelo dinheiro), guarda e controla as operações. Sem ela, nenhuma decisão sai do papel, e um erro pequeno pode virar um prejuízo grande.", "naPratica": "A área existe em bancos, corretoras, gestoras, administradoras e custodiantes de fundos e na própria B3."}, {"titulo": "Front, middle e back office", "texto": "Front office é quem negocia; middle office confere as operações e o risco e faz a ponte entre a mesa e o back office; back office registra e liquida. Boleta é o registro de uma operação (ativo, quantidade, preço, cliente, data, contraparte).", "naPratica": "Uma estagiária de operações confere boletas, faz conciliações simples e apoia o fechamento."}, {"titulo": "Conciliação", "texto": "Conciliar é comparar o sistema interno com a custódia, o banco e as contrapartes e explicar cada diferença antes de ajustar.", "naPratica": "Ajustar um número só para as fontes baterem esconde o problema. Primeiro se descobre a causa."}, {"titulo": "Controles e incidentes", "texto": "Dupla checagem, segregação de funções (quem negocia não liquida) e trilhas de aprovação reduzem erro e fraude. Quando um incidente acontece, a resposta é avisar e seguir o procedimento.", "naPratica": "Esconder ou corrigir sozinha, sem registro, é pior do que atrasar o fechamento."}], "comoSeEntra": {"ondeSeTrabalha": "Bancos, corretoras, gestoras, administradoras e custodiantes de fundos e a própria B3, em equipes como back office, middle office, custódia, controladoria de fundos, cadastro e prevenção à lavagem de dinheiro e tesouraria operacional.", "formacoes": "A área recebe candidatas de várias formações. Conferir com profissionais da área.", "vagas": "Estágio e analista júnior em back office, middle office e controladoria de fundos.", "oQueAjuda": "Atenção a detalhe, organização, Excel avançado e noções de SQL e Python. Certificações do PQO da B3 e da ANBIMA são pedidas em algumas funções (conferir).", "quandoRecrutam": "Vagas fecham rápido: acompanhe as páginas de carreira de gestoras, administradoras, corretoras e bancos."}}$$::jsonb,
  'publicado',
  13
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  'op-complexo',
  'Operações completo: a cota que caiu 10%',
  'operacoes',
  'Descubra por que a cota de um fundo caiu quase 10% num dia de bolsa estável, calcule a cota correta e decida o que fazer antes da divulgação.',
  'Descobrir o que aconteceu, calcular a cota correta, decidir o que fazer com a divulgação às 19h e propor controles para que o erro não se repita.',
  $$Você trabalha como estagiária na controladoria de fundos da Arquipélago. São 18h15 e o sistema calculou a cota do Fundo Arquipélago Ações (fictício) com uma queda de quase 10% no dia, num dia em que a bolsa ficou estável. A cota é divulgada aos cotistas às 19h. Sua missão é descobrir o que aconteceu, calcular a cota correta, decidir o que fazer com a divulgação e propor controles para que isso não se repita. Valores fictícios, em reais. "Hoje" é o dia D0. Fundo: 1.000.000 de cotas (não houve aplicações nem resgates hoje); cota de ontem de R$ 9,90 (patrimônio de R$ 9.900.000); taxa de administração de 1,5% ao ano, provisionada todo dia sobre o patrimônio do dia anterior, base de 252 dias úteis.$$,
  $${"resumo": "Na controladoria de fundos, a cota é calculada todos os dias: o patrimônio do fundo dividido pelo número de cotas. Quando um evento não é lançado ou uma fonte não bate, a cota sai errada. Neste case, você investiga uma queda suspeita, concilia as fontes, recalcula a cota e decide o que fazer antes da divulgação.", "links": [], "cards": [{"titulo": "Cota de fundo e patrimônio", "texto": "A cota é o patrimônio do fundo dividido pelo número de cotas, calculada todo dia. O patrimônio soma os ativos (marcados a mercado), o caixa e valores a receber e subtrai o que o fundo deve e as provisões, como a taxa de administração.", "naPratica": "A taxa de administração é provisionada todo dia na cota, o que reduz o patrimônio diariamente."}, {"titulo": "Eventos corporativos", "texto": "Dividendos, juros sobre capital próprio, desdobramentos e grupamentos mudam posições e valores. As datas \"com\" e \"ex\" definem quem tem direito: quem tem a ação na data \"com\" recebe; na \"ex\", o preço já não inclui o direito.", "naPratica": "Se um desdobramento não é lançado no sistema, a quantidade de ações fica antiga enquanto o preço já mudou."}, {"titulo": "Conciliação com várias fontes", "texto": "Compare o sistema interno, a custódia (B3) e o extrato do banco e explique cada diferença antes de ajustar. Algumas diferenças são normais, como uma compra que ainda não liquidou.", "naPratica": "Nem toda diferença exige ajuste: saber reconhecer a diferença normal evita corrigir o que está certo."}, {"titulo": "Decidir sob horário-limite", "texto": "Quando o número está errado perto do horário de divulgação, o caminho é não divulgar o erro, corrigir, validar com uma segunda pessoa e com o administrador do fundo, e avisar a gerente. Se não der tempo, atrasa-se a divulgação com comunicação aos envolvidos.", "naPratica": "Um bom controle impede o erro de chegar ao cotista: por exemplo, um alerta de variação de cota que bloqueia a divulgação até a revisão."}], "comoSeEntra": {"ondeSeTrabalha": "Administradoras e gestoras de fundos, bancos, corretoras, custodiantes e a B3, na controladoria de fundos, no back office e no middle office.", "formacoes": "A área recebe candidatas de várias formações. Conferir com profissionais da área.", "vagas": "Estágio e analista júnior em back office, middle office e controladoria de fundos.", "oQueAjuda": "Excel avançado, SQL e noções de Python ou de ferramentas de automação são o diferencial mais citado nas vagas de operações.", "quandoRecrutam": "Vagas fecham rápido: acompanhe as páginas de carreira de administradoras, gestoras e bancos."}}$$::jsonb,
  'publicado',
  14
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO contents (id, title, type, area_id, summary, body, url, minutes, case_ids) VALUES
($$op-areas$$, $$Front, middle e back office, boleta e liquidação$$, $$artigo$$, 'operacoes', $$Quem faz o quê numa operação e como o ativo troca de mãos.$$, $$**Front office** é quem negocia (a mesa); **middle office** confere as operações e o risco e é a ponte entre a mesa e o back office; **back office** registra e liquida. A **boleta** é o registro da operação: ativo, quantidade, preço, cliente ou fundo, data e contraparte, além das datas de negociação e de liquidação. **Liquidação** é a troca efetiva do ativo pelo dinheiro. Em ações na B3, em geral acontece dois dias úteis depois (D+2); títulos públicos liquidam no sistema Selic, do Banco Central (conferir prazos atuais com a área). **Custódia** é a guarda dos ativos em nome do dono, registrada numa central depositária, como a da B3.$$, NULL, 6, '["op-simplificado"]'::jsonb),
($$op-conciliacao$$, $$Conciliação: comparar fontes e explicar diferenças$$, $$artigo$$, 'operacoes', $$Como comparar sistema, custódia e banco antes de ajustar qualquer número.$$, $$**Conciliar** é comparar o sistema interno com a custódia, o banco e as contrapartes. O passo a passo é: identificar a diferença, investigar movimentações e eventos recentes (resgates, compras ainda não liquidadas, eventos corporativos, tarifas), achar a causa, confirmar e só então ajustar e registrar o ajuste. Nem toda diferença é erro: uma compra feita hoje que liquida em D+2 ainda não aparece na custódia, e isso é normal. Ajustar um número só para as fontes baterem, sem entender a causa, esconde o problema.$$, NULL, 6, '["op-simplificado", "op-complexo"]'::jsonb),
($$op-controles$$, $$Controles, risco operacional, PLD e KYC$$, $$artigo$$, 'operacoes', $$Dupla checagem, segregação de funções e o que fazer diante de sinais de fraude.$$, $$**Risco operacional** é a perda por falha de processo, de sistema ou de pessoas (erro de digitação, sistema fora do ar, fraude). Os **controles** reduzem esse risco: dupla checagem, **segregação de funções** (quem negocia não liquida nem confere) e trilhas de aprovação. **PLD** (prevenção à lavagem de dinheiro) e **KYC** (conheça seu cliente) envolvem cadastro, origem dos recursos e atenção a operações estranhas, e operações participa porque enxerga as movimentações. Um pedido urgente por e-mail para trocar a conta de destino de um resgate é um sinal clássico de fraude: nada muda sem confirmar pelo canal oficial. Diante de um incidente, avise na hora e siga o procedimento, registrando o que foi feito.$$, NULL, 6, '["op-simplificado", "op-complexo"]'::jsonb),
($$op-cx-cota$$, $$Cota de fundo, marcação a mercado e taxa de administração$$, $$glossario$$, 'operacoes', $$Como o patrimônio vira cota e como a taxa de administração entra no cálculo.$$, $$A **cota** é o patrimônio do fundo dividido pelo número de cotas, calculada todo dia. A **marcação a mercado** atualiza o valor dos ativos pelo preço de mercado do dia. A **taxa de administração** é cobrada do fundo e provisionada todo dia na cota: a provisão diária é o patrimônio do dia anterior multiplicado pela taxa ao ano e dividido por 252 dias úteis, e ela reduz o patrimônio todos os dias. A **rentabilidade do dia** é a variação da cota em relação à cota de ontem.$$, NULL, 5, '["op-complexo"]'::jsonb),
($$op-cx-eventos$$, $$Eventos corporativos: dividendos, JCP, desdobramento e datas com/ex$$, $$glossario$$, 'operacoes', $$O que muda na posição e no preço quando ocorre um evento corporativo.$$, $$**Dividendos** e **juros sobre capital próprio (JCP)** são formas de distribuir lucro. Quem tem a ação na data **"com"** recebe; na data **"ex"**, o preço já não inclui o direito, então cai e o valor passa a ser um valor a receber, pago em uma data posterior. No **desdobramento**, as ações se multiplicam e o preço se divide (por exemplo, de 1 para 2: o dobro de ações a metade do preço); no **grupamento**, ocorre o contrário. O valor total da posição não muda. Se o sistema não registra o evento, a quantidade fica antiga e o patrimônio fica errado.$$, NULL, 5, '["op-complexo"]'::jsonb),
($$op-onde-estudar$$, $$Onde estudar mais sobre Operações$$, $$artigo$$, 'operacoes', $$Fontes e práticas sugeridas para os conceitos, os cases e a carreira.$$, $$**Para os conceitos e os cases:** Bora Investir, da B3 (textos simples sobre liquidação, custódia, clearing e eventos corporativos); manuais e regulamentos da B3 sobre a câmara de compensação e a central depositária (leitura de consulta, não de ponta a ponta); regulação de fundos da CVM (Resolução 175) e a regra de prevenção à lavagem de dinheiro (Resolução CVM 50), lendo os resumos e guias oficiais, não a norma inteira; códigos da ANBIMA para administração e gestão de recursos; o livro "Mercado Financeiro", de Alexandre Assaf Neto; e prática em Excel, montando uma conciliação de posições entre duas fontes e um cálculo de cota. **Para a carreira:** Excel avançado, SQL e noções de Python ou de ferramentas de automação são o diferencial mais citado nas vagas; certificações do PQO da B3 (como back office e custódia) e da ANBIMA aparecem como requisito ou diferencial em algumas vagas; e ler descrições de vagas de back office, middle office e controladoria de fundos ajuda a entender o vocabulário (boletagem, conciliação, zeragem de caixa, cotas). Regras, prazos e certificações devem ser conferidos com uma profissional da área.$$, NULL, 6, '["op-simplificado", "op-complexo"]'::jsonb)
ON CONFLICT (id) DO NOTHING;

