($$op-cp-4$$, 'op-simplificado', 4, $$situacao$$, $$Capítulo 2: conciliação$$, $$Descubra a causa mais provável de uma diferença entre sistema e custódia e o próximo passo.$$, 30, $$["op-task-conciliacao"]$$::jsonb),
