($$op-cp-7$$, 'op-simplificado', 7, $$defesa$$, $$Capítulo 5: a banca$$, $$Responda a Ricardo, Paula e Helena sobre impacto, controle e comunicação.$$, 40, $$["op-task-banca"]$$::jsonb),
($$op-cx-cp-1$$, 'op-complexo', 1, $$entenda$$, $$Cota, conciliação e incidentes$$, $$Entenda como a cota é calculada, como se concilia entre fontes e como se decide perto do horário de divulgação.$$, 15, $$[]$$::jsonb),
($$op-cx-cp-2$$, 'op-complexo', 2, $$conteudos$$, $$Conteúdos do case$$, $$Leia todos os conteúdos do case antes de recalcular a cota.$$, 10, $$[]$$::jsonb),
($$op-cx-cp-3$$, 'op-complexo', 3, $$situacao$$, $$A cota do sistema$$, $$Calcule o patrimônio e a cota que o sistema gerou e explique por que o alerta de queda disparou.$$, 30, $$["op-cx-task-cota-sistema"]$$::jsonb),
($$op-cx-cp-4$$, 'op-complexo', 4, $$situacao$$, $$Conciliação das três fontes$$, $$Compare sistema, custódia e banco, indique a causa e o ajuste de cada diferença e reconheça a que é normal.$$, 40, $$["op-cx-task-conciliacao"]$$::jsonb),
($$op-cx-cp-5$$, 'op-complexo', 5, $$situacao$$, $$A cota correta$$, $$Recalcule o patrimônio, a cota e a rentabilidade do dia.$$, 35, $$["op-cx-task-cota-correta"]$$::jsonb),
($$op-cx-cp-6$$, 'op-complexo', 6, $$situacao$$, $$Decisão das 18h15$$, $$Decida o que fazer com a divulgação das 19h e quem precisa ser avisado.$$, 30, $$["op-cx-task-decisao"]$$::jsonb),
($$op-cx-cp-7$$, 'op-complexo', 7, $$situacao$$, $$Relatório de incidente$$, $$Escreva o relatório de uma página com o que aconteceu, o impacto, as causas e a correção.$$, 35, $$["op-cx-task-incidente"]$$::jsonb),
($$op-cx-cp-8$$, 'op-complexo', 8, $$defesa$$, $$Prevenção$$, $$Proponha três controles e uma automação para que esses erros não se repitam.$$, 40, $$["op-cx-task-prevencao"]$$::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO tasks (id, case_id, checkpoint_id, title, prompt, fields, support_data, answer_key) VALUES
($$op-task-conferencia$$, 'op-simplificado', $$op-cp-3$$, $$Capítulo 1: conferência$$,
$$Quinta-feira, 16h40. Você é estagiária de operações da Arquipélago. Todas as ordens do dia precisam ser conferidas e enviadas para liquidação até as 18h. Marina, a gerente, está em reunião até as 17h30.
[[continuar]]
Marina: “Nada sai daqui com erro. Confira as seis ordens.”
Eva: “Para cada ordem: o valor bate com quantidade vezes preço? Alguma coisa mudou hoje?”
[[continuar]]
[[campos: ordem_1, ordem_2, ordem_3, ordem_4, ordem_5, ordem_6, motivo]]
Para cada ordem, indique se está correta ou qual é o problema. Depois, explique em poucas palavras o que te fez marcar cada ordem com problema.$$,
$$[{"id": "ordem_1", "tipo": "opcao", "rotulo": "Ordem 1: Fundo Arquipélago Crédito, compra de debênture Energia Sul", "obrigatorio": true, "opcoes": ["Correta", "Duplicada", "Valor errado", "Risco de fraude", "Quantidade errada"]}, {"id": "ordem_2", "tipo": "opcao", "rotulo": "Ordem 2: Fundo Arquipélago Crédito, compra de debênture Energia Sul (mesmo horário da ordem 1)", "obrigatorio": true, "opcoes": ["Correta", "Duplicada", "Valor errado", "Risco de fraude", "Quantidade errada"]}, {"id": "ordem_3", "tipo": "opcao", "rotulo": "Ordem 3: Cliente Lúcia M., resgate de fundo (conta de destino alterada hoje, por e-mail)", "obrigatorio": true, "opcoes": ["Correta", "Duplicada", "Valor errado", "Risco de fraude", "Quantidade errada"]}, {"id": "ordem_4", "tipo": "opcao", "rotulo": "Ordem 4: Fundo Arquipélago Ações, venda de 10.000 ações XYZ3 (preço do dia: R$ 18,20)", "obrigatorio": true, "opcoes": ["Correta", "Duplicada", "Valor errado", "Risco de fraude", "Quantidade errada"]}, {"id": "ordem_5", "tipo": "opcao", "rotulo": "Ordem 5: Fundo Arquipélago Ações, compra de 5.000 ações ABC3 (preço do dia: R$ 22,00)", "obrigatorio": true, "opcoes": ["Correta", "Duplicada", "Valor errado", "Risco de fraude", "Quantidade errada"]}, {"id": "ordem_6", "tipo": "opcao", "rotulo": "Ordem 6: Fundo Arquipélago Renda Fixa, compra de 200 Tesouro Selic", "obrigatorio": true, "opcoes": ["Correta", "Duplicada", "Valor errado", "Risco de fraude", "Quantidade errada"]}, {"id": "motivo", "tipo": "texto", "rotulo": "Em poucas palavras, o que te fez marcar as ordens com problema?", "obrigatorio": true, "limiteCaracteres": 500}]$$::jsonb,
$${"titulo": "As ordens do dia", "colunas": ["Cliente", "Operação", "Quantidade", "Valor (R$)", "Observação"], "linhas": [{"rotulo": "Ordem 1", "celulas": [{"texto": "Fundo Arquipélago Crédito", "valor": null}, {"texto": "Compra de debênture Energia Sul", "valor": null}, {"texto": "1.000", "valor": 1000}, {"texto": "1.020.000", "valor": 1020000}, {"texto": "—", "valor": null}]}, {"rotulo": "Ordem 2", "celulas": [{"texto": "Fundo Arquipélago Crédito", "valor": null}, {"texto": "Compra de debênture Energia Sul", "valor": null}, {"texto": "1.000", "valor": 1000}, {"texto": "1.020.000", "valor": 1020000}, {"texto": "Mesmo horário da ordem 1", "valor": null}]}, {"rotulo": "Ordem 3", "celulas": [{"texto": "Cliente Lúcia M.", "valor": null}, {"texto": "Resgate de fundo", "valor": null}, {"texto": "—", "valor": null}, {"texto": "250.000", "valor": 250000}, {"texto": "Conta de destino alterada hoje, por e-mail", "valor": null}]}, {"rotulo": "Ordem 4", "celulas": [{"texto": "Fundo Arquipélago Ações", "valor": null}, {"texto": "Venda de 10.000 ações XYZ3", "valor": null}, {"texto": "10.000", "valor": 10000}, {"texto": "182.000", "valor": 182000}, {"texto": "Preço do dia: R$ 18,20", "valor": null}]}, {"rotulo": "Ordem 5", "celulas": [{"texto": "Fundo Arquipélago Ações", "valor": null}, {"texto": "Compra de 5.000 ações ABC3", "valor": null}, {"texto": "5.000", "valor": 5000}, {"texto": "1.100.000", "valor": 1100000}, {"texto": "Preço do dia: R$ 22,00", "valor": null}]}, {"rotulo": "Ordem 6", "celulas": [{"texto": "Fundo Arquipélago Renda Fixa", "valor": null}, {"texto": "Compra de Tesouro Selic", "valor": null}, {"texto": "200", "valor": 200}, {"texto": "3.000.000", "valor": 3000000}, {"texto": "—", "valor": null}]}]}$$::jsonb,
$${"referencias": {"ordem_1": "Correta", "ordem_2": "Duplicada", "ordem_3": "Risco de fraude", "ordem_4": "Correta", "ordem_5": "Valor errado", "ordem_6": "Correta"}, "explicacoes": {"ordem_2": "A ordem 2 repete a ordem 1 no mesmo horário: está duplicada.", "ordem_3": "A troca da conta de destino por e-mail, no mesmo dia, é sinal de fraude: não segue sem confirmar pelo canal oficial.", "ordem_5": "5.000 × R$ 22,00 = R$ 110.000, e não R$ 1.100.000: o valor está errado.", "corretas": "As ordens 1, 4 (10.000 × R$ 18,20 = R$ 182.000) e 6 estão corretas."}, "dicaEva": "Para cada ordem: o valor bate com quantidade vezes preço? Alguma coisa mudou hoje?", "rubrica": "Critério 1 da rubrica: atenção a detalhe (1 a 4)."}$$::jsonb),
($$op-task-conciliacao$$, 'op-simplificado', $$op-cp-4$$, $$Capítulo 2: conciliação$$,
$$Enquanto confere as ordens, você também concilia as posições antes do envio para liquidação.
[[continuar]]
Eva: “Olha esta diferença. O sistema mostra 50.000 cotas de um fundo para um cliente, mas a custódia mostra 48.000. No histórico, há um pedido de resgate de 2.000 cotas ontem.”
[[campos: causa, proximo_passo]]
Escolha a causa mais provável e o próximo passo.$$,
$$[{"id": "causa", "tipo": "opcao", "rotulo": "Qual é a causa mais provável da diferença?", "obrigatorio": true, "opcoes": ["A. A custódia perdeu 2.000 cotas por erro dela.", "B. O resgate de 2.000 cotas de ontem não foi lançado no sistema.", "C. O cliente comprou 2.000 cotas a mais ontem.", "D. É uma diferença normal de prazo de liquidação e não precisa de investigação."]}, {"id": "proximo_passo", "tipo": "opcao", "rotulo": "Qual é o próximo passo?", "obrigatorio": true, "opcoes": ["A. Ajustar o sistema para 48.000 agora, para as posições baterem.", "B. Pedir à custódia que volte para 50.000 cotas.", "C. Confirmar o resgate antes de ajustar e, então, ajustar e registrar o ajuste.", "D. Deixar a diferença para o fechamento do mês."]}]$$::jsonb,
